package com.creatio.autotest.testdata.models;

/**
 * Результат выполнения активности Creatio — значение дропдауна «Результат»
 * (маркеры поля {@code Result} / {@code ProcessResult}) в попапе активности.
 * <p>
 * Закрытый набор выбираемых значений, ранее захардкоженный строкой «Выполнена»
 * в десяти стадийных флоу (розница и Агро). Централизует happy-path результат
 * в одном источнике.
 * <p>
 * Сейчас содержит только подтверждённое по коду значение {@link #COMPLETED}.
 * Значения негативных путей (отказ/возврат) добавляются в рамках негативных
 * сценариев (NEW1.2) — по подтверждению с живого DOM конкретного дропдауна,
 * а не догадкой: результат активности и отказ по заявке могут оказаться
 * разными механизмами UI.
 */
public enum ActivityResult {

    /** «Выполнена» — штатное завершение активности (happy-path). */
    COMPLETED("Выполнена");

    private final String uiText;

    ActivityResult(String uiText) {
        this.uiText = uiText;
    }

    /** Текст результата, как он отображается в дропдауне активности Creatio. */
    public String getUiText() {
        return uiText;
    }
}